const d = $input.first().json || {};
const alur = d.workflow && d.workflow.name ? d.workflow.name : '(tanpa nama)';
const ex = d.execution || {};
const err = ex.error || {};
const pesanError = String(err.message || 'tanpa pesan error').replace(/\s+/g, ' ').trim().slice(0, 300);
const node = String(ex.lastNodeExecuted || (err.node && err.node.name) || '-').trim();
const eksekusi = String(ex.id || '-');
const waktu = new Date(Date.now() + 7 * 3600 * 1000).toISOString().slice(0, 19).replace('T', ' ');
const baris = [
  'Workflow gagal: ' + alur,
  'Node: ' + node,
  'Waktu: ' + waktu + ' WIB',
  'Execution: ' + eksekusi,
  '',
  pesanError,
];
if (ex.url) baris.push('', String(ex.url));
return [{ json: { output: baris.join('\n') } }];

const esc = (v) => v === null || v === undefined ? 'null' : "'" + String(v).replace(/'/g, "''") + "'";
const workflowName = "Error Handler - Finance";
return $input.all().map((item) => {
  const m = (item && item.json) || {};
  const p = m.result && typeof m.result === 'object' ? m.result : m;
  const chatId = p.chat && p.chat.id ? p.chat.id : null;
  const messageId = p.message_id === undefined ? null : p.message_id;
  const text = p.text === undefined ? '' : p.text;
  const executionId = $execution && $execution.id ? $execution.id : '';
  const sql = "insert into public.conversation_logs (chat_id, message_id, direction, kind, text, intent, workflow, execution_id) values (" + (chatId === null ? "null" : chatId) + ", " + (messageId === null ? "null" : messageId) + ", 'out', 'text', " + esc(text) + ", null, " + esc(workflowName) + ", " + esc(executionId) + ")";
  return { json: { sql } };
});
